// ============================================
// TRANSFORMATION FOURNISSEUR -> PRESTASHOP 1.7.4
// Elockstore.com
// ============================================

const items = $input.all();
const results = [];

// Helper functions
function slugify(text) {
  if (!text) return '';
  return text.toString().toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .substring(0, 128);
}

function parsePrice(value) {
  if (!value) return '';
  let v = value.toString().replace(/[€$£\s]/g, '');
  const lastComma = v.lastIndexOf(',');
  const lastDot = v.lastIndexOf('.');
  if (lastComma > lastDot) {
    v = v.replace(/\./g, '').replace(',', '.');
  } else if (lastDot > lastComma) {
    v = v.replace(/,/g, '');
  } else {
    v = v.replace(',', '.');
  }
  const num = parseFloat(v);
  return isNaN(num) ? '' : num.toFixed(6);
}

function parseInt2(value) {
  if (!value) return '0';
  const v = parseInt(value.toString().replace(/,/g, '.'));
  return isNaN(v) ? '0' : v.toString();
}

function cleanEan(value) {
  if (!value) return '';
  let v = value.toString().replace(/[^\d]/g, '');
  if (v.length === 12) v = '0' + v;
  return v.length === 13 ? v : (v.length <= 13 ? v : v.substring(0, 13));
}

function titleCase(text) {
  if (!text) return '';
  const small = new Set(['de','du','des','le','la','les','un','une','et','ou','en','à','au','aux','pour','par','sur','avec','sans']);
  return text.split(' ').map((w, i) => {
    if (i === 0 || !small.has(w.toLowerCase())) {
      return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
    }
    return w.toLowerCase();
  }).join(' ');
}

function truncate(text, max) {
  if (!text) return '';
  text = text.toString().trim();
  return text.length <= max ? text : text.substring(0, max - 3) + '...';
}

function cleanHtml(text) {
  if (!text) return '';
  return text.toString().trim().replace(/\r\n/g, '<br>').replace(/\n/g, '<br>');
}

// Mapping auto-detect des colonnes source
function findField(item, patterns) {
  for (const key of Object.keys(item)) {
    const keyLower = key.toLowerCase().replace(/[^a-z0-9]/g, '');
    for (const p of patterns) {
      if (keyLower === p || keyLower.includes(p)) {
        return item[key];
      }
    }
  }
  return '';
}

// Category mapping
const categoryMap = {
  'serrure': 'Accueil > Serrures',
  'cylindre': 'Accueil > Cylindres',
  'verrou': 'Accueil > Verrous',
  'cadenas': 'Accueil > Cadenas',
  'poignee': 'Accueil > Poignées',
  'accessoire': 'Accueil > Accessoires',
  'coffre': 'Accueil > Coffres-forts',
  'alarme': 'Accueil > Alarmes',
  'video': 'Accueil > Vidéosurveillance',
  'controle': "Accueil > Contrôle d'accès",
  'domotique': 'Accueil > Domotique',
};

function mapCategory(value) {
  if (!value) return 'Accueil';
  const lower = value.toString().toLowerCase();
  for (const [key, cat] of Object.entries(categoryMap)) {
    if (lower.includes(key)) return cat;
  }
  return 'Accueil > ' + value.toString().trim();
}

for (const item of items) {
  const data = item.json;

  // Extraire les champs avec auto-detection
  const ref = (findField(data, ['ref','reference','sku','code','article']) || '').toString().trim();
  const ean = cleanEan(findField(data, ['ean','ean13','gtin','barcode','codebarre']));
  const name = titleCase(findField(data, ['nom','name','designation','libelle','titre','produit']));
  const shortDesc = cleanHtml(findField(data, ['desccourte','shortdesc','resume','shortdescription','descriptioncourte']));
  const desc = cleanHtml(findField(data, ['desc','description','descriptionlongue','longdescription','detail']));
  const priceHT = parsePrice(findField(data, ['pvht','prixht','prixventeht','priceht','priceexcl','prixhorstaxe']));
  const priceTTC = parsePrice(findField(data, ['pvttc','prixttc','prixventettc','pricettc','priceincl']));
  const wholesale = parsePrice(findField(data, ['paht','prixachat','cost','wholesale','prixachatht','pa']));
  const qty = parseInt2(findField(data, ['qty','qte','quantite','quantity','stock']));
  const weight = findField(data, ['poids','weight','kg']).toString().replace(',', '.');
  const category = mapCategory(findField(data, ['cat','categorie','category','famille','rayon']));
  const brand = (findField(data, ['marque','brand','manufacturer','fabricant']) || '').toString().trim();
  const supplier = (findField(data, ['fournisseur','supplier','vendor']) || '').toString().trim();
  const supplierRef = (findField(data, ['reffournisseur','supplierref','refsupplier','supplierreference']) || '').toString().trim();
  const imageUrl = (findField(data, ['image','img','photo','urlimage','imageurl','picture']) || '').toString().trim();
  const ecotax = parsePrice(findField(data, ['ecotaxe','ecotax']));

  if (!name) continue;

  const slug = slugify(name);
  const metaTitle = truncate(name + ' - Elockstore.com', 70);
  const metaDesc = shortDesc ? 
    truncate(shortDesc.replace(/<[^>]+>/g, ''), 160) : 
    truncate('Achetez ' + name + ' sur Elockstore.com. Livraison rapide et prix compétitifs.', 160);

  results.push({
    json: {
      'ID': '',
      'Active (0/1)': '1',
      'Name *': name,
      'Categories (x,y,z...)': category,
      'Price tax excluded': priceHT,
      'Price tax included': priceTTC,
      'Tax rule ID': '1',
      'Wholesale price': wholesale,
      'On sale (0/1)': '0',
      'Discount amount': '',
      'Discount percent': '',
      'Discount from (yyyy-mm-dd)': '',
      'Discount to (yyyy-mm-dd)': '',
      'Reference': ref,
      'Supplier reference': supplierRef || ref,
      'Supplier': supplier,
      'Manufacturer': brand,
      'EAN13': ean,
      'UPC': '',
      'MPN': '',
      'Ecotax': ecotax,
      'Width': '',
      'Height': '',
      'Depth': '',
      'Weight': weight,
      'Delivery time of in-stock products': 'Livraison sous 2-5 jours ouvrés',
      'Delivery time of out-of-stock products': 'Livraison sous 7-14 jours ouvrés',
      'Quantity': qty,
      'Minimal quantity': '1',
      'Low stock level': '',
      'Send me an email when the quantity is under this level (0/1)': '0',
      'Visibility': 'both',
      'Additional shipping cost': '',
      'Unity': '',
      'Unit price': '',
      'Short description': shortDesc,
      'Description': desc || shortDesc,
      'Tags (x,y,z...)': '',
      'Meta title': metaTitle,
      'Meta keywords': '',
      'Meta description': metaDesc,
      'URL rewritten': slug,
      'Text when in stock': 'En stock',
      'Text when backorder allowed': 'Produit en cours de réapprovisionnement',
      'Available for order (0/1)': '1',
      'Product availability date': '',
      'Product creation date': '',
      'Show price (0/1)': '1',
      'Image URLs (x,y,z...)': imageUrl,
      'Image alt texts (x,y,z...)': imageUrl ? name : '',
      'Delete existing images (0/1)': '0',
      'Feature (Name:Value:Position:Customized)': '',
      'Available online only (0/1)': '0',
      'Condition': 'new',
      'Customizable (0/1)': '0',
      'Uploadable files (0/1)': '0',
      'Text fields (0/1)': '0',
      'Out of stock action': '',
      'Virtual product (0/1)': '0',
      'File URL': '',
      'Number of allowed downloads': '',
      'Expiration date (yyyy-mm-dd)': '',
      'Number of days': '',
      'ID / Name of shop': '',
      'Advanced Stock Management': '0',
      'Depends on stock': '0',
      'Warehouse': '',
      'Accessories (x,y,z...)': ''
    }
  });
}

return results;

