// Logging & Statistiques
const items = $input.all();
const count = items.length;

console.log(`[PrestaShop Import] ${count} produits transformés avec succès`);
console.log(`[PrestaShop Import] Date: ${new Date().toISOString()}`);

// Vérification de qualité
let warnings = [];
for (const item of items) {
  const d = item.json;
  if (!d['Reference']) warnings.push(`Produit "${d['Name *']}" sans référence`);
  if (!d['Price tax excluded'] && !d['Price tax included']) warnings.push(`Produit "${d['Name *']}" sans prix`);
  if (!d['EAN13']) warnings.push(`Produit "${d['Name *']}" sans EAN13`);
}

if (warnings.length > 0) {
  console.log(`[PrestaShop Import] ${warnings.length} avertissements:`);
  for (const w of warnings) {
    console.log(`  - ${w}`);
  }
}

return items;
